import{_ as t,I as r,g as o,j as e}from"./chunks/framework.Ha9mtr6N.js";const u=JSON.parse('{"title":"Капитал (Управленческий баланс)","description":"Как ОмниКрафт ЕРП рассчитывает стоимость вашего бизнеса, распределение активов и личные инвестиции.","frontmatter":{"title":"Капитал (Управленческий баланс)","description":"Как ОмниКрафт ЕРП рассчитывает стоимость вашего бизнеса, распределение активов и личные инвестиции.","order":11},"headers":[],"relativePath":"ru/docs/spaces/production/capital.md","filePath":"ru/docs/spaces/production/capital.md"}'),s={name:"ru/docs/spaces/production/capital.md"};function n(i,a,l,p,c,d){return r(),o("div",null,[...a[0]||(a[0]=[e('<div class="warning custom-block"><p class="custom-block-title">📌 Документация находится в разработке</p><p><strong>Уважаемые пользователи!</strong></p><p>Поскольку ОмниКрафт ЕРП сейчас находится в стадии активной бета-версии, регулярно дорабатывается и расширяется, справочные материалы также обновляются постепенно.</p><p>На данный момент воспринимайте документацию как ориентировочную — она является неполной, может временно не содержать описание некоторых функций или содержать неточности.</p></div><h1 id="💼-капитал-управленческии-баланс-бизнеса" tabindex="-1">💼 Капитал: Управленческий баланс бизнеса <a class="header-anchor" href="#💼-капитал-управленческии-баланс-бизнеса" aria-label="Permalink to &quot;💼 Капитал: Управленческий баланс бизнеса&quot;">​</a></h1><p>Вкладка <strong>«Капитал»</strong> — это финансовый пульс вашего бизнеса в реальном времени. В отличие от ДДС, который показывает движение живых денег, Капитал отвечает на главный вопрос собственника: <strong>«Сколько стоит мой бизнес прямо сейчас, если я решу его закрыть или продать?»</strong>.</p><p>Здесь программа автоматически собирает все материальные ценности мастерской и вычитает из них внешние долги, формируя ваш <strong>Собственный капитал (Net Worth)</strong>.</p><hr><h2 id="📊-главная-цифра-итого-капитал-бизнеса" tabindex="-1">📊 Главная цифра: Итого капитал бизнеса <a class="header-anchor" href="#📊-главная-цифра-итого-капитал-бизнеса" aria-label="Permalink to &quot;📊 Главная цифра: Итого капитал бизнеса&quot;">​</a></h2><p>В самом верху экрана вы видите крупную цифру — это чистая стоимость вашего бизнеса. Она рассчитывается по фундаментальной формуле управленческого учета:</p><p>$$\\text{Капитал} = \\text{Все активы мастерской} - \\text{Обязательства (Долги)}$$</p><p>Если цифра положительная и растет от месяца к месяцу — ваш бизнес богатеет, даже если в кассе (ДДС) прямо сейчас мало свободных денег (например, вы закупили много кожи впрок или купили новый станок).</p><hr><h2 id="🥧-распределение-активов-структура-бизнеса" tabindex="-1">🥧 Распределение активов (Структура бизнеса) <a class="header-anchor" href="#🥧-распределение-активов-структура-бизнеса" aria-label="Permalink to &quot;🥧 Распределение активов (Структура бизнеса)&quot;">​</a></h2><p>Ниже главного показателя программа наглядно показывает, <strong>в какой форме</strong> сейчас заморожены ваши деньги. Бизнес-активы делятся на четыре основные категории, для каждой из которых отрисован прогресс-бар с процентным соотношением:</p><h3 id="_1-💵-свободные-деньги-касса" tabindex="-1">1. 💵 Свободные деньги (Касса) <a class="header-anchor" href="#_1-💵-свободные-деньги-касса" aria-label="Permalink to &quot;1. 💵 Свободные деньги (Касса)&quot;">​</a></h3><p>Это ваш текущий положительный баланс ДДС. Деньги, которые физически лежат на счету или в наличной кассе и готовы к немедленному использованию (на зарплату, новые закупки или вывод себе в карман).</p><h3 id="_2-📦-сырье-на-складе" tabindex="-1">2. 📦 Сырьё на складе <a class="header-anchor" href="#_2-📦-сырье-на-складе" aria-label="Permalink to &quot;2. 📦 Сырьё на складе&quot;">​</a></h3><p>Стоимость всех материалов, рассчитанная по методу <strong>MAC (средневзвешенная цена)</strong>. Это ваши «замороженные» деньги в виде кожи, фурнитуры, клея и ниток, которые еще не превратились в готовые изделия.</p><h3 id="_3-🛍️-готовые-изделия-на-витрине" tabindex="-1">3. 🛍️ Готовые изделия на витрине <a class="header-anchor" href="#_3-🛍️-готовые-изделия-на-витрине" aria-label="Permalink to &quot;3. 🛍️ Готовые изделия на витрине&quot;">​</a></h3><p>Стоимость товаров, которые вы уже сшили, но еще не продали. Они оценены по их фактической себестоимости (с учетом FIFO-партий). Как только товар продается, его стоимость перетекает из этого блока в свободные деньги (выручку) и прибыль.</p><h3 id="_4-🛠️-оборудование-и-инструменты-мастерская" tabindex="-1">4. 🛠️ Оборудование и инструменты (Мастерская) <a class="header-anchor" href="#_4-🛠️-оборудование-и-инструменты-мастерская" aria-label="Permalink to &quot;4. 🛠️ Оборудование и инструменты (Мастерская)&quot;">​</a></h3><p>Остаточная стоимость всех ваших станков, прессов и дорогих инструментов с учетом накопленной амортизации (износа). Это ваш производственный фундамент.</p><hr><h2 id="🛡️-личные-инвестиции-отрицательная-касса" tabindex="-1">🛡️ Личные инвестиции (Отрицательная касса) <a class="header-anchor" href="#🛡️-личные-инвестиции-отрицательная-касса" aria-label="Permalink to &quot;🛡️ Личные инвестиции (Отрицательная касса)&quot;">​</a></h2><p>Иногда в блоке распределения активов вы можете увидеть специфический красный блок: <strong>«Личные инвестиции»</strong>.</p><p><strong>Что это значит?</strong> В философии ОмниКрафт ЕРП (в рамках смешанных финансов) сальдо ДДС может уходить в минус. Это не ошибка бухгалтерии, а честный показатель того, что на старте или в периоды кассовых разрывов вы вкладывали <strong>свои личные деньги</strong> (например, с зарплатной карты) в покупку сырья или оборудования для мастерской.</p><ul><li><strong>Как это работает:</strong> Если ваш ДДС в минусе на 50 000 ₽, программа показывает это как «Личные инвестиции». Это значит, что бизнес «должен» вам 50 000 ₽.</li><li><strong>Когда это исчезнет?</strong> Как только бизнес начнет стабильно генерировать прибыль и сальдо ДДС пересечет нулевую отметку, блок «Личных инвестиций» исчезнет. Это будет означать, что бизнес полностью вернул вам вложенные личные средства и начал работать на собственной самоокупаемости.</li></ul><div class="tip custom-block"><p class="custom-block-title">Как читать Капитал и ДДС вместе?</p><ul><li><strong>ДДС</strong> показывает, сколько у вас прямо сейчас <em>живых денег</em> на оплату счетов.</li><li><strong>Капитал</strong> показывает, насколько <em>богат ваш бизнес</em> в целом (станки + кожа на полке + готовые сумки + деньги в кассе).</li></ul></div>',26)])])}const g=t(s,[["render",n]]);export{u as __pageData,g as default};
